-- ALTER TABLE ADD: DEFAULT ... WITH VALUES, PERIOD FOR SYSTEM_TIME, INDEX; masking functions with quotes
ALTER TABLE t ADD a int NULL, b varchar(10) NOT NULL CONSTRAINT df_b DEFAULT 'x' WITH VALUES;

ALTER TABLE t ADD c int DEFAULT 0 WITH VALUES;

ALTER TABLE t ADD PERIOD FOR SYSTEM_TIME (vf, vt);

ALTER TABLE t ADD vf datetime2 GENERATED ALWAYS AS ROW START HIDDEN NOT NULL DEFAULT sysutcdatetime(), vt datetime2 GENERATED ALWAYS AS ROW END HIDDEN NOT NULL DEFAULT '9999-12-31', PERIOD FOR SYSTEM_TIME (vf, vt);

ALTER TABLE t ADD INDEX ix NONCLUSTERED (a);

ALTER TABLE t ADD CONSTRAINT df DEFAULT 0 FOR a WITH VALUES;

ALTER TABLE t ALTER COLUMN s ADD MASKED WITH (FUNCTION = 'partial(1,"XX",0)');

CREATE TABLE t (s varchar(10) MASKED WITH (FUNCTION = 'partial(1,''X'',0)'));
